"""cut2_appB.py -- compress Appendix B toward the register form: design, eligibility, consent, reference standard, battery,
endpoint decision, power, pre-registered secondary outcomes, analysis plan and timeline all kept; Table (B.5) and
Table (B.7) become sentences; verbatim prompts untouched."""
import re
P = "/home/claude/work/src/docs/chapters/_pending/appendix_b.md"
t = open(P, encoding="utf-8").read()
before = len(t.split())
def sub1(old, new):
    global t
    assert t.count(old) == 1, (old[:70], t.count(old)); t = t.replace(old, new)
def drop_table(caption_prefix):
    global t
    L = t.split("\n")
    a = next(k for k, l in enumerate(L) if l.startswith(caption_prefix))
    b = a + 1
    while b < len(L) and (L[b].startswith("|") or not L[b].strip()): b += 1
    del L[a:b]; t = "\n".join(L)

